input.new_str:
@classmethod
def can_parse(cls, dct):
    """
    This needs to ignore can_parse since the objects it's parsing are not
    regular - they must always have only one key though.
    Empty dictionaries are also valid (indicating no security required).
    """
    # Empty dictionary is valid (no security required)
    if len(dct.keys()) == 0:
        return True
    # Regular security requirement with one key whose value is a list
    return len(dct.keys()) == 1 and isinstance([c for c in dct.values()][0], list)

def __getstate__(self):
